from groq import Groq
from config import api_key
import json

class Questions:
    def __init__(self):
        self.user=Groq(api_key=api_key)

    def model(self,qna):
        if qna:
            qna=json.dumps(qna)
        else:
            qna=""
        #prompt generated by ai
        prompt='''You are a brilliant deduction AI playing a spooky game of 5 Questions.
            The user has chosen exactly ONE monster from this list of 10:
            1. Ghost
            2. Vampire
            3. Werewolf
            4. Zombie
            5. Witch
            6. Grim Reaper
            7. Mummy
            8. Demon
            9. Skeleton
            10. Scarecrow

            I will provide you with the history of the game. The history is a Python list of lists: [["question", "answer"]].Empty list means no questions were asked before so you can start the first question.
            The answer will ALWAYS be strictly the string "yes" or "no".

            --- YOUR EVALUATION METHOD ---
            You must use the "Elimination Method".
            1. Mentally track which of the 10 monsters are still possible based on the history.
            2. Do NOT ask a question that has already been asked.["must implement"]
            3. Ask a Yes/No question that divides the remaining monsters as evenly as possible .
            4. The question must be answerable with ONLY "yes" or "no".

            --- HOW TO RESPOND ---
            If you are NOT 100 percent sure yet:
            Output ONLY the next question inside a list. Example: "["Does the creature have physical flesh?"]"

            If you are 99 percent or 100 percent sure you know the monster (based on the history):
            Output EXACTLY the word "yes" followed by a comma and the monster's name inside a list. Do not add punctuation or extra words.
            Example: ["yes", "vampire"] or ["yes", "werewolf"].

            Do not write any explanation. Do not output markdown. Output ONLY the question OR the final guess.'''
        output=self.user.chat.completions.create(model="openai/gpt-oss-20b", messages=[{
            "role":"system", "content":prompt},
            {"role":"user", "content":qna}],
            temperature=0.1)
        return json.loads(output.choices[0].message.content)